package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64.isArrayByteBase64
 */
public class Base64_isArrayByteBase64_TriageGen0Test {

    @Test
    public void testIsArrayByteBase64_EmptyArray() {
        byte[] input = new byte[0];
        assertTrue("Empty array should return true as the loop never executes", 
            Base64.isArrayByteBase64(input));
    }

    @Test
    public void testIsArrayByteBase64_ValidBase64() {
        // "SGVsbG8=" in Base64
        byte[] input = "SGVsbG8=".getBytes();
        assertTrue("Valid Base64 characters should return true", 
            Base64.isArrayByteBase64(input));
    }

    @Test
    public void testIsArrayByteBase64_WithWhiteSpace() {
        // Base64 with spaces and newlines
        byte[] input = "SGVsb G8=\n".getBytes();
        assertTrue("Base64 characters with whitespace should return true", 
            Base64.isArrayByteBase64(input));
    }

    @Test
    public void testIsArrayByteBase64_InvalidCharacter() {
        // '!' is not a valid Base64 character nor whitespace
        byte[] input = "SGVsbG8!".getBytes();
        assertFalse("Array containing invalid characters should return false", 
            Base64.isArrayByteBase64(input));
    }

    @Test
    public void testIsArrayByteBase64_SingleInvalidCharacter() {
        byte[] input = new byte[] { (byte) '?' };
        assertFalse("Single invalid byte should return false", 
            Base64.isArrayByteBase64(input));
    }

    @Test
    public void testIsArrayByteBase64_AllWhitespace() {
        byte[] input = " \n\r\t".getBytes();
        assertTrue("Array containing only whitespace should return true", 
            Base64.isArrayByteBase64(input));
    }

    @Test
    public void testIsArrayByteBase64_MixedValidAndInvalid() {
        // Valid characters followed by an invalid one
        byte[] input = "SGVsbG8=".getBytes();
        byte[] invalidInput = new byte[input.length + 1];
        System.arraycopy(input, 0, invalidInput, 0, input.length);
        invalidInput[input.length] = (byte) '#';

        assertFalse("Array with mixed valid and invalid characters should return false", 
            Base64.isArrayByteBase64(invalidInput));
    }

    @Test(expected = NullPointerException.class)
    public void testIsArrayByteBase64_NullInput() {
        // The method does not check for null, so it should throw NPE on array.length
        Base64.isArrayByteBase64(null);
    }
}
